import { CSPProvider } from "@/registry/erbium/ui/csp-provider";
import { SkeletonProvider } from "@/registry/erbium/ui/skeleton";
import { Toaster } from "@/registry/erbium/ui/toast";
import type { ReactNode } from "react";

export const ShowcaseProviders = ({
  children,
  toast = false,
}: {
  children?: ReactNode;
  toast?: boolean;
}) => (
  <CSPProvider disableStyleElements>
    <SkeletonProvider>
      {children}
      {toast && <Toaster />}
    </SkeletonProvider>
  </CSPProvider>
);

export const ShowcaseSurface = ({ children }: { children?: ReactNode }) => (
  <div
    data-slot="component-preview"
    className="relative isolate mx-auto flex min-h-64 w-full min-w-0 max-w-3xl items-center justify-center gap-section p-5 font-sans text-foreground contain-layout sm:p-8 [&>.min-w-72.max-w-2xl]:flex [&>.min-w-72.max-w-2xl]:flex-col [&>.min-w-72.max-w-2xl]:items-center [&>.min-w-72.max-w-2xl]:justify-center"
  >
    {children}
  </div>
);

import { Icon } from "@/registry/erbium/ui/icon";

import { Toggle } from "@/registry/erbium/ui/toggle";

export default function ToggleExample() {
  return (
    <Toggle
      aria-label="Toggle bookmark"
      size="sm"
      variant="outline"
      className="data-[state=on]:bg-transparent data-[state=on]:*:[svg]:fill-info data-[state=on]:*:[svg]:stroke-info"
    >
      <Icon name="bookmark-01" />
      Bookmark
    </Toggle>
  );
}

import { Icon } from "@/registry/erbium/ui/icon";

import { Toggle } from "@/registry/erbium/ui/toggle";

export default function ToggleDisabledExample() {
  return (
    <Toggle aria-label="Toggle italic" disabled>
      <Icon name="underline" className="h-4 w-4" />
    </Toggle>
  );
}

import { Icon } from "@/registry/erbium/ui/icon";

import { Toggle } from "@/registry/erbium/ui/toggle";

export default function ToggleOutlineExample() {
  return (
