import { ShowcaseProviders, ShowcaseSurface } from "../preview";
import type { Meta, StoryObj } from "@storybook/react";

import { Toggle } from "@/registry/erbium/ui/toggle";

import PlaygroundExample, { defaultProps as PlaygroundDefaults } from "./variants/playground";



import OverviewExample from "./variants/overview";



import PressedExample from "./variants/pressed";



import DisabledControlExample from "./variants/disabled-control";



import OutlineExample from "./variants/outline";



import DisabledExample from "./variants/disabled";



import WithTextExample from "./variants/with-text";



import SizeExample from "./variants/size";



const meta = {
  component: Toggle,
  parameters: {
    docs: {
      description: {
        component: "A button with an on or off state.\n\n**Import:** `@/registry/erbium/ui/toggle`\n\n## Usage\n\n```tsx\nimport { Toggle } from \"@/registry/erbium/ui/toggle\";\n```\n\n```tsx\n<Toggle>Toggle</Toggle>\n```\n\n## Base UI documentation\n\nExplore the underlying primitives and their API reference.\n\n- [Toggle](https://base-ui.com/react/components/toggle)",
      },
    },
    layout: "centered",
  },
  tags: ["autodocs"],
} satisfies Meta<typeof Toggle>;

export default { ...meta, title: "Components/Toggle",  decorators: [(Story, context) => <ShowcaseProviders toast={false && context.viewMode !== "docs"}><ShowcaseSurface><Story /></ShowcaseSurface></ShowcaseProviders>] } satisfies Meta;

type Story = StoryObj;

export const Playground: StoryObj<typeof Toggle> = {
  argTypes: {
    defaultPressed: { control: "boolean" },
    size: { control: "select", options: ["default", "sm", "lg"] },
    variant: { control: "select", options: ["default", "outline"] },
  },
  args: PlaygroundDefaults,
  parameters: {
    docs: {
      description: { story: "" },
      source: { code: "import { Toggle } from \"@/registry/erbium/ui/toggle\";\nimport type * as React from \"react\";\n\nexport const defaultProps = {\n  className: \"\",\n  defaultPressed: false,\n  size: \"default\",\n  variant: \"default\",\n} satisfies React.ComponentProps<typeof Toggle>;\n\nexport default function TogglePlaygroundExample(\n  args: React.ComponentProps<typeof Toggle> = defaultProps,\n) {\n  return <Toggle {...args}>Toggle</Toggle>;\n}\n" },
    },
  },
  render: PlaygroundExample,
};

export const Overview: Story = {
  parameters: {
    docs: {
      description: { story: "" },
      source: { code: "import { Icon } from \"@/registry/erbium/ui/icon\";\n\nimport { Toggle } from \"@/registry/erbium/ui/toggle\";\n\nexport default function ToggleExample() {\n  return (\n    <Toggle\n      aria-label=\"Toggle bookmark\"\n      size=\"sm\"\n      variant=\"outline\"\n      className=\"data-[state=on]:bg-transparent data-[state=on]:*:[svg]:fill-info data-[state=on]:*:[svg]:stroke-info\"\n    >\n      <Icon name=\"bookmark-01\" />\n      Bookmark\n    </Toggle>\n  );\n}\n" },
    },
  },
  render: OverviewExample,
};

export const Pressed: Story = {
  parameters: {
    docs: {
      description: { story: "Start a toggle in the pressed state." },
      source: { code: "import { Toggle } from \"@/registry/erbium/ui/toggle\";\n\nexport default function TogglePressedExample() {\n  return (\n    <Toggle defaultPressed aria-label=\"Bold\">\n      Bold\n    </Toggle>\n  );\n}\n" },
    },
  },
  render: PressedExample,
};

export const DisabledControl: Story = {
  parameters: {
    docs: {
      description: { story: "Disable a toggle to prevent interaction." },
      source: { code: "import { Toggle } from \"@/registry/erbium/ui/toggle\";\n\nexport default function ToggleDisabledControlExample() {\n  return (\n    <Toggle disabled aria-label=\"Unavailable\">\n      Disabled\n    </Toggle>\n  );\n}\n" },
    },
  },
  render: DisabledControlExample,
};

export const Outline: Story = {
  parameters: {
    docs: {
      description: { story: "Use `variant=\"outline\"` for an outline style." },
      source: { code: "import { Icon } from \"@/registry/erbium/ui/icon\";\n\nimport { Toggle } from \"@/registry/erbium/ui/toggle\";\n\nexport default function ToggleOutlineExample() {\n  return (\n    <Toggle variant=\"outline\" aria-label=\"Toggle italic\">\n      <Icon name=\"italic\" />\n    </Toggle>\n  );\n}\n" },
    },
  },
  render: OutlineExample,
};

export const Disabled: Story = {
  parameters: {
    docs: {
      description: { story: "Show a disabled toggle." },
      source: { code: "import { Icon } from \"@/registry/erbium/ui/icon\";\n\nimport { Toggle } from \"@/registry/erbium/ui/toggle\";\n\nexport default function ToggleDisabledExample() {\n  return (\n    <Toggle aria-label=\"Toggle italic\" disabled>\n      <Icon name=\"underline\" className=\"h-4 w-4\" />\n    </Toggle>\n  );\n}\n" },
    },
  },
  render: DisabledExample,
