export const WithText: Story = {
  parameters: {
    docs: {
      description: { story: "Pair a toggle icon with a text label." },
      source: { code: "import { Icon } from \"@/registry/erbium/ui/icon\";\n\nimport { Toggle } from \"@/registry/erbium/ui/toggle\";\n\nexport default function ToggleTextExample() {\n  return (\n    <Toggle aria-label=\"Toggle italic\">\n      <Icon name=\"italic\" />\n      Italic\n    </Toggle>\n  );\n}\n" },
    },
